  const MARKETS={steady:{name:'平穩市場',stock:.06,bond:.025,inflation:.02,unemployment:1},growth:{name:'景氣擴張',stock:.12,bond:.02,inflation:.025,unemployment:.6},recession:{name:'景氣衰退',stock:-.16,bond:.015,inflation:.01,unemployment:2},inflation:{name:'通膨升溫',stock:.02,bond:-.04,inflation:.05,unemployment:1.2}};
