  function record(s,title,detail,kind='period'){s.history.push({age:s.age,title,detail,kind});}
  function create(input){const s={...input,position:0,startAge:input.age,startNet:0,remaining:0,die:0,market:'steady',marketPeriods:0,unemployed:0,policies:{life:false,accident:false,medical:false},history:[],series:[],ended:false,reason:null,totalPremium:0,totalClaims:0,totalIncome:0,totalExpense:0,totalInterest:0,totalPrincipal:0,forcedSales:0,shortfall:0,survivorBenefit:0,periods:0,events:0};s.startNet=net(s);s.series.push({age:s.age,net:net(s)});record(s,'人生開始','已建立客戶資料。生活費按輸入總額計算，房產不自動變現。','start');return s;}
  function fund(s){if(s.cash>=0)return;for(const key of ['bonds','stocks']){const sold=Math.min(s[key],-s.cash);s[key]-=sold;s.cash+=sold;s.forcedSales+=sold;if(sold>0)record(s,'為支出變現投資',`賣出${key==='bonds'?'債券':'股票'} ${round(sold)} 元，補足現金缺口。`,'sale');}if(s.cash<0){s.shortfall=-s.cash;s.cash=0;s.ended=true;s.reason='bankruptcy';record(s,'必要支出無法支付',`可變現資產耗盡，尚欠 ${round(s.shortfall)} 元；房產不自動出售。`,'end');}}
