  function advance(s,rng=Math.random){if(s.ended||s.remaining<=0)return null;const before=net(s),market=MARKETS[s.market],retired=s.age>=65;const earned=round(income(s)/2),living=round(s.expense/2),fees=round(premium(s)/2),interest=round(s.debt*s.interest/200),paid=Math.min(round(s.repayment/2),s.debt);const equityReturn=market.stock/2+(rng()-.5)*.18,bondReturn=market.bond/2+(rng()-.5)*.035;const stocks=round(s.stocks*equityReturn),bonds=round(s.bonds*bondReturn);s.stocks=Math.max(0,s.stocks+stocks);s.bonds=Math.max(0,s.bonds+bonds);s.cash+=earned-living-fees-interest-paid;s.debt-=paid;s.totalIncome+=earned;s.totalExpense+=living;s.totalPremium+=fees;s.totalInterest+=interest;s.totalPrincipal+=paid;s.age+=.5;s.position=(s.position+1)%20;s.remaining--;s.periods++;s.expense=round(s.expense*(1+market.inflation/2));if(s.unemployed>0)s.unemployed--;record(s,'半年財務結算',`收入 +${earned}／生活費 −${living}／保費 −${fees}／利息 −${interest}／還本金 −${paid}／股票 ${stocks>=0?'+':''}${stocks}／債券 ${bonds>=0?'+':''}${bonds} 元。`);fund(s);if(!s.ended&&s.age===65)record(s,'進入退休階段',`往後工作收入停止，退休年收入改為 ${s.pension} 元。`,'milestone');if(s.marketPeriods>0&&--s.marketPeriods===0){s.market='steady';record(s,'市場回到平穩情境','此版以固定期限結束市場情境，並非預測。','market');}const mortality=s.age<50?.0008:s.age<65?.002:s.age<80?.012:s.age<90?.05:.15;if(!s.ended&&(s.age>=100||rng()<mortality*(s.health==='chronic'?1.7:1)))die(s,s.age>=100?'抵達原型壽命上限（100歲）':'生命自然終止（教學機率）');s.series.push({age:s.age,net:net(s)});return {earned,living,fees,interest,paid,stocks,bonds,before,after:net(s),retired};}
  function cost(s,amount,type){const cover=type&&s.policies[type]?POLICIES[type].cover:0;const claim=Math.min(amount,cover);s.totalClaims+=claim;s.cash-=amount-claim;fund(s);return {loss:amount,claim,own:amount-claim};}
  function event(s,rng=Math.random){if(s.ended)return null;const cat=CATEGORIES[s.position%4],pick=rng();s.events++;let title='',text='',lesson='',numbers=null;
    if(cat==='market'){const k=pick<.34?'recession':pick<.67?'inflation':'growth';s.market=k;s.marketPeriods=4;if(k==='recession'){title='景氣降溫，市場進入衰退';text='未來兩年採衰退情境：股票承壓，工作中斷風險升高。';lesson='收入與投資可能同時受影響。預備金讓你少一點被迫賣出的壓力。';}else if(k==='inflation'){title='同樣的生活，開始變貴';text='未來兩年採高通膨情境；貸款年利率提高1個百分點，最高30%。';s.interest=Math.min(30,s.interest+1);lesson='生活成本、貸款與投資會一起改變。現金金額不變，不代表購買力不變。';}else{title='景氣擴張，市場轉暖';text='未來兩年採擴張情境，股票有較高的模擬平均報酬，但仍會波動。';lesson='好的行情不會消除未來風險。不要只因為最近上漲，就把近期要用的錢全部投入。';}}
    else if(cat==='accident'){const illnessChance=s.health==='chronic'?.6:.35;if(pick<illnessChance){title='疾病需要治療';text='發生一筆35萬元的疾病醫療支出。';numbers=cost(s,350000,'medical');lesson='疾病與意外是不同的保障範圍。醫療給付後，超過上限的費用仍須自行負擔。';}else if(pick<.75){title='交通意外，住院治療';text='發生一筆25萬元的意外醫療支出。';numbers=cost(s,250000,'accident');lesson='意外醫療保障可以填補部分費用，但不會補償這張教學卡未列入的所有損失。';}else if(pick<.97){title='居家設備突發損壞';text='需要8萬元維修費，這三種教學保障都不承保。';numbers=cost(s,80000,null);lesson='保險不能涵蓋每一種支出。小額突發費用仍需要可動用的現金。';}else{title='重大意外，人生突然停止';text='此模擬人生因重大意外身故。';lesson='壽險無法避免事故。它的作用是讓留下的家人有資金處理後續生活與負債。';die(s,'重大意外');}}
    else if(cat==='work'){if(s.age>=65){if(pick<.5){title='退休後的短期顧問邀約';text='收到6萬元一次性顧問收入。';s.cash+=60000;lesson='額外收入能改善現金流，但不宜假定每年都會持續。';}else{title='退休生活步入日常';text='工作收入已停止，生活由退休收入與資產支應。';lesson='提款期間的市場波動，會改變剩餘資產能支撐多久。';}}else{const base=s.jobType==='stable'?.24:s.jobType==='variable'?.36:.42;const chance=Math.min(.8,base*MARKETS[s.market].unemployment);if(pick<chance){title='工作收入中斷';s.unemployed=2;text='接下來一年沒有工作收入，一年後恢復原收入水準（教學假設）。';lesson='醫療與身故保障不等於失業保障。生活預備金直接決定這一年能否度過。';}else if(pick<.78){title='努力得到回報';s.income=round(s.income*1.08);text='年度工作收入增加8%。';lesson='收入增加提供更多規劃空間。先看家庭缺口，再決定增加支出或投資。';}else{title='職涯維持穩定';text='這段時間工作收入維持原來水準。';lesson='平穩時期是累積預備金與整理保障的機會。';}}}
    else{if(pick<.34){title='家庭責任增加';s.dependents++;s.expense+=60000;text='新增一位需要扶養的家人，年生活費增加6萬元。';lesson='保障需求會隨家庭責任改變。檢查保額是否足以處理扶養與負債。';}else if(pick<.67){title='家人需要一筆支援';text='家庭照顧或教育支出需要12萬元。';numbers=cost(s,120000,null);lesson='可預見或突發的家庭支出，都需要對應資金；不是所有缺口都由保險處理。';}else{title='與重要的人留下回憶';text='一趟旅行與相聚花費3萬元。';numbers=cost(s,30000,null);lesson='財務規劃也要支持現在的生活。評估這筆支出是否會影響必要準備。';}}
    record(s,title,`${text}${numbers?` 損失 ${numbers.loss}／給付 ${numbers.claim}／自付 ${numbers.own} 元。`:''}`,'event');s.series[s.series.length-1]={age:s.age,net:net(s)};return {cat,title,text,lesson,numbers};}
  function transfer(s,from,to,amount){if(s.ended)return '人生已結束，無法調整。';if(!['cash','stocks','bonds'].includes(from)||!['cash','stocks','bonds'].includes(to)||from===to)return '請選擇不同的資產。';if(!Number.isFinite(amount)||amount<=0||!Number.isInteger(amount))return '請輸入正整數金額。';if(amount>s[from])return '來源資產不足，請減少金額。';s[from]-=amount;s[to]+=amount;record(s,'調整資產配置',`${from} → ${to}：${amount} 元。`,'decision');return null;}
